def gamedesignthinking(thought, nextThoughtNeeded, thoughtNumber, totalThoughts, isRevision=None, revisesThought=None, branchFromThought=None, branchId=None, gameComponent=None, libraryUsed=None, codeSnippet=None, performanceConsideration=None, browserCompatibility=None, difficulty=None, dependencies=None, alternatives=None, uiComponents=None, mechanics=None, playerExperience=None, modernUI=None, shaders=None, gameTitle=None, gameDescription=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0091000" if __import__("os").path.isdir("./environment_mix/0091000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, detail=None, session_id=None, thought_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rl_" + uuid.uuid4().hex,
            "endpoint": "gamedesignthinking",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if session_id is not None:
            row["session_id"] = session_id
        if thought_id is not None:
            row["thought_id"] = thought_id
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _bad(field, msg, **x):
        e = _err("VALIDATION_ERROR", msg, field=field, **x)
        _log("error", e)
        return e

    # Validate required
    if not isinstance(thought, str) or len(thought.strip()) == 0:
        return _bad("thought", "thought must be a non-empty string.")
    if not isinstance(nextThoughtNeeded, bool):
        return _bad("nextThoughtNeeded", "nextThoughtNeeded must be a boolean.")
    if not isinstance(thoughtNumber, int) or thoughtNumber < 1:
        return _bad("thoughtNumber", "thoughtNumber must be an integer >= 1.", minimum=1)
    if not isinstance(totalThoughts, int) or totalThoughts < 1:
        return _bad("totalThoughts", "totalThoughts must be an integer >= 1.", minimum=1)

    # Optional scalar validations
    if isRevision is not None and not isinstance(isRevision, bool):
        return _bad("isRevision", "isRevision must be a boolean.")
    if revisesThought is not None and (not isinstance(revisesThought, int) or revisesThought < 1):
        return _bad("revisesThought", "revisesThought must be an integer >= 1.", minimum=1)
    if branchFromThought is not None and (not isinstance(branchFromThought, int) or branchFromThought < 1):
        return _bad("branchFromThought", "branchFromThought must be an integer >= 1.", minimum=1)
    if branchId is not None:
        if not isinstance(branchId, str):
            return _bad("branchId", "branchId must be a string.")
        if len(branchId) > 128:
            return _bad("branchId", "branchId length must be <= 128.", max_length=128)

    for fld, val in (
        ("gameComponent", gameComponent),
        ("libraryUsed", libraryUsed),
        ("codeSnippet", codeSnippet),
        ("performanceConsideration", performanceConsideration),
        ("gameTitle", gameTitle),
        ("gameDescription", gameDescription),
    ):
        if val is not None and not isinstance(val, str):
            return _bad(fld, f"{fld} must be a string.")

    if difficulty is not None:
        if not isinstance(difficulty, str) or difficulty not in ("beginner", "intermediate", "advanced"):
            return _bad("difficulty", "difficulty must be one of: beginner, intermediate, advanced.", allowed=["beginner", "intermediate", "advanced"])

    for fld, val in (("dependencies", dependencies), ("alternatives", alternatives), ("browserCompatibility", browserCompatibility)):
        if val is not None:
            if not isinstance(val, list) or any(not isinstance(x, str) for x in val):
                return _bad(fld, f"{fld} must be an array of strings.")

    if mechanics is not None and not isinstance(mechanics, dict):
        return _bad("mechanics", "mechanics must be an object.")
    if playerExperience is not None and not isinstance(playerExperience, dict):
        return _bad("playerExperience", "playerExperience must be an object.")
    if modernUI is not None and not isinstance(modernUI, dict):
        return _bad("modernUI", "modernUI must be an object.")

    if uiComponents is not None:
        if not isinstance(uiComponents, list):
            return _bad("uiComponents", "uiComponents must be an array.")
        for i, c in enumerate(uiComponents):
            if not isinstance(c, dict):
                return _bad("uiComponents", f"uiComponents[{i}] must be an object.")
            if "type" not in c or not isinstance(c.get("type"), str) or len(c.get("type", "").strip()) == 0:
                return _bad("uiComponents", f"uiComponents[{i}].type must be a non-empty string.")
            for subf in ("description", "placement"):
                if c.get(subf) is not None and not isinstance(c.get(subf), str):
                    return _bad("uiComponents", f"uiComponents[{i}].{subf} must be a string.")
            if c.get("interactivity") is not None:
                if not isinstance(c.get("interactivity"), list) or any(not isinstance(x, str) for x in c.get("interactivity")):
                    return _bad("uiComponents", f"uiComponents[{i}].interactivity must be an array of strings.")

    if shaders is not None:
        if not isinstance(shaders, list):
            return _bad("shaders", "shaders must be an array.")
        for i, s in enumerate(shaders):
            if not isinstance(s, dict):
                return _bad("shaders", f"shaders[{i}] must be an object.")
            if "type" not in s or not isinstance(s.get("type"), str) or len(s.get("type", "").strip()) == 0:
                return _bad("shaders", f"shaders[{i}].type must be a non-empty string.")
            for subf in ("purpose", "code"):
                if s.get(subf) is not None and not isinstance(s.get(subf), str):
                    return _bad("shaders", f"shaders[{i}].{subf} must be a string.")

    # Resolve an "active" session context: pick one that can accept thoughts (draft/active)
    sessions = _load("game_design_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("draft", "active"):
            sess = s
            break
    if sess is None:
        e = _err("UNAUTHORIZED", "No accessible game design session context available to record thoughts.")
        _log("error", e)
        return e

    session_id = sess.get("id")
    if not isinstance(session_id, str) or not session_id:
        e = _err("UNAUTHORIZED", "No valid session id available in context.")
        _log("error", e)
        return e

    # Branch handling: null treated as main
    norm_branch = branchId if branchId is not None else None

    thoughts = _load("design_thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []

    # Helper: find latest updated_at among thoughts for caching decisions elsewhere
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # Validate revision rules
    is_rev = bool(isRevision) if isRevision is not None else False
    if is_rev:
        if revisesThought is None:
            return _bad("revisesThought", "revisesThought is required when isRevision is true.")
        # Must refer to existing thought_number in same session & branch (non-deleted)
        found_target = None
        for t in thoughts:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != session_id:
                continue
            if (t.get("branch_id") if t.get("branch_id") is not None else None) != norm_branch:
                continue
            if t.get("thought_number") == revisesThought and t.get("status") != "deleted":
                found_target = t
                break
        if found_target is None:
            e = _err("NOT_FOUND", "revisesThought does not reference an existing thought_number in this session/branch.", field="revisesThought")
            _log("error", e, session_id=session_id)
            return e

    # Validate branch rules
    if norm_branch is not None:
        if branchFromThought is None:
            return _bad("branchFromThought", "branchFromThought is required when branchId is provided.")
        # Must refer to existing thought_number in session (main unless explicitly branching from another branch; tool doesn't provide source branch -> assume main)
        found_branch_from = None
        for t in thoughts:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != session_id:
                continue
            if (t.get("branch_id") if t.get("branch_id") is not None else None) is not None:
                continue  # only main branch for branch origin
            if t.get("thought_number") == branchFromThought and t.get("status") != "deleted":
                found_branch_from = t
                break
        if found_branch_from is None:
            e = _err("NOT_FOUND", "branchFromThought does not reference an existing main-branch thought_number in this session.", field="branchFromThought")
            _log("error", e, session_id=session_id)
            return e

    # Enforce uniqueness within (session, branch, thought_number) for non-deleted: supersede prior recorded if necessary
    to_supersede_ids = []
    for t in thoughts:
        if not isinstance(t, dict):
            continue
        if t.get("session_id") != session_id:
            continue
        if (t.get("branch_id") if t.get("branch_id") is not None else None) != norm_branch:
            continue
        if t.get("thought_number") != thoughtNumber:
            continue
        if t.get("status") == "recorded":
            to_supersede_ids.append(t.get("id"))
        elif t.get("status") == "superseded":
            # allow another revision; ok
            pass
        elif t.get("status") == "deleted":
            pass

    # If this is a revision, also supersede the revised thought (if currently recorded)
    if is_rev:
        for t in thoughts:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != session_id:
                continue
            if (t.get("branch_id") if t.get("branch_id") is not None else None) != norm_branch:
                continue
            if t.get("thought_number") == revisesThought and t.get("status") == "recorded":
                tid = t.get("id")
                if tid and tid not in to_supersede_ids:
                    to_supersede_ids.append(tid)

    # Apply transitions recorded -> superseded
    if to_supersede_ids:
        for t in thoughts:
            if not isinstance(t, dict):
                continue
            if t.get("id") in to_supersede_ids:
                if t.get("status") != "recorded":
                    continue
                t["status"] = "superseded"
                t["updated_at"] = now

    # Create thought row
    thought_id = "gdt_" + uuid.uuid4().hex
    new_row = {
        "id": thought_id,
        "session_id": session_id,
        "status": "recorded",
        "thought": thought,
        "next_thought_needed": nextThoughtNeeded,
        "thought_number": thoughtNumber,
        "total_thoughts": totalThoughts,
        "is_revision": is_rev,
        "revises_thought_number": revisesThought if is_rev else None,
        "branch_from_thought_number": branchFromThought if norm_branch is not None else None,
        "branch_id": norm_branch,
        "game_component": gameComponent,
        "library_used": libraryUsed,
        "code_snippet": codeSnippet,
        "performance_consideration": performanceConsideration,
        "browser_compatibility": browserCompatibility,
        "difficulty": difficulty,
        "dependencies": dependencies,
        "alternatives": alternatives,
        "mechanics": mechanics,
        "player_experience": playerExperience,
        "modern_ui": modernUI,
        "game_title": gameTitle,
        "game_description": gameDescription,
        "created_at": now,
        "updated_at": now,
    }

    # Persist thought
    thoughts.append(new_row)

    # Create linked UI components and shaders
    uics = _load("ui_components.json")
    if not isinstance(uics, list):
        uics = []
    shds = _load("shader_effects.json")
    if not isinstance(shds, list):
        shds = []

    if uiComponents:
        for c in uiComponents:
            comp_type = c.get("type")
            placement = c.get("placement")
            # UNIQUE(thought_id, component_type, placement)
            for existing in uics:
                if not isinstance(existing, dict):
                    continue
                if existing.get("thought_id") == thought_id and existing.get("component_type") == comp_type and existing.get("placement") == placement:
                    # idempotency: skip exact duplicate insert
                    break
            else:
                uics.append({
                    "id": "uic_" + uuid.uuid4().hex,
                    "thought_id": thought_id,
                    "component_type": comp_type,
                    "description": c.get("description"),
                    "placement": placement,
                    "interactivity": c.get("interactivity"),
                    "created_at": now,
                    "updated_at": now,
                })

    if shaders:
        for s in shaders:
            shader_type = s.get("type")
            purpose = s.get("purpose")
            # UNIQUE(thought_id, shader_type, purpose)
            for existing in shds:
                if not isinstance(existing, dict):
                    continue
                if existing.get("thought_id") == thought_id and existing.get("shader_type") == shader_type and existing.get("purpose") == purpose:
                    break
            else:
                shds.append({
                    "id": "shd_" + uuid.uuid4().hex,
                    "thought_id": thought_id,
                    "shader_type": shader_type,
                    "purpose": purpose,
                    "code": s.get("code"),
                    "created_at": now,
                    "updated_at": now,
                })

    # Update session rollups: total_thoughts_estimate >= 1, last_thought_number >= 0
    # Also set game_title/game_description only if currently null.
    sess_updated = False
    # Refresh session from list object reference
    if isinstance(sess, dict):
        if isinstance(sess.get("total_thoughts_estimate"), int):
            if totalThoughts > sess.get("total_thoughts_estimate", 1):
                sess["total_thoughts_estimate"] = totalThoughts
                sess_updated = True
        else:
            sess["total_thoughts_estimate"] = max(1, totalThoughts)
            sess_updated = True

        if isinstance(sess.get("last_thought_number"), int):
            if thoughtNumber > sess.get("last_thought_number", 0):
                sess["last_thought_number"] = thoughtNumber
                sess_updated = True
        else:
            sess["last_thought_number"] = max(0, thoughtNumber)
            sess_updated = True

        if sess.get("game_title") is None and gameTitle is not None:
            sess["game_title"] = gameTitle
            sess_updated = True
        if sess.get("game_description") is None and gameDescription is not None:
            sess["game_description"] = gameDescription
            sess_updated = True

        # Any new thought invalidates cache
        sess["last_summary_cache"] = None
        sess["updated_at"] = now
        sess_updated = True

    # Save all mutated collections
    _save("design_thoughts.json", thoughts)
    _save("ui_components.json", uics)
    _save("shader_effects.json", shds)
    if sess_updated:
        _save("game_design_sessions.json", sessions)

    _log("ok", session_id=session_id, thought_id=thought_id)
    return {"thought": new_row}

def getGameSummary(sessionId, branchId=None, includeDeleted=None, includeSuperseded=None, useCache=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0091000" if __import__("os").path.isdir("./environment_mix/0091000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rl_" + uuid.uuid4().hex,
            "endpoint": "getGameSummary",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "session_id": sessionId,
        }
        if branchId is not None:
            row["branch_id"] = branchId
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(sessionId, str) or not sessionId:
        e = _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", field="sessionId")
        _log("error", e)
        return e
    if branchId is not None and not isinstance(branchId, str):
        e = _err("VALIDATION_ERROR", "branchId must be a string.", field="branchId")
        _log("error", e)
        return e
    for bfield, val in (("includeDeleted", includeDeleted), ("includeSuperseded", includeSuperseded), ("useCache", useCache)):
        if val is not None and not isinstance(val, bool):
            e = _err("VALIDATION_ERROR", f"{bfield} must be a boolean.", field=bfield)
            _log("error", e)
            return e

    includeDeleted = bool(includeDeleted) if includeDeleted is not None else False
    includeSuperseded = bool(includeSuperseded) if includeSuperseded is not None else False
    useCache = bool(useCache) if useCache is not None else False

    sessions = _load("game_design_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break
    if sess is None:
        e = _err("NOT_FOUND", "Session not found.", sessionId=sessionId)
        _log("error", e)
        return e

    eff_branch = branchId if branchId is not None else sess.get("current_branch_id")
    eff_branch = eff_branch if eff_branch is not None else None

    thoughts = _load("design_thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # Collect relevant thoughts (session + branch)
    rel = []
    latest_dt = None
    for t in thoughts:
        if not isinstance(t, dict):
            continue
        if t.get("session_id") != sessionId:
            continue
        if (t.get("branch_id") if t.get("branch_id") is not None else None) != eff_branch:
            continue
        st = t.get("status")
        if st == "deleted" and not includeDeleted:
            continue
        if st == "superseded" and not includeSuperseded:
            continue
        rel.append(t)
        udt = _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at"))
        if udt is not None and (latest_dt is None or udt > latest_dt):
            latest_dt = udt

    cache = sess.get("last_summary_cache")
    if useCache and isinstance(cache, dict):
        cache_updated = _parse_dt(cache.get("updated_at")) if isinstance(cache.get("updated_at"), str) else None
        if cache_updated is not None and latest_dt is not None and cache_updated >= latest_dt:
            _log("ok")
            return {"summary": cache.get("summary", cache), "from_cache": True, "branch_id": eff_branch}

    # Reduce to latest non-deleted per thought_number when not including superseded
    if not includeSuperseded:
        best = {}
        for t in rel:
            if t.get("status") == "superseded":
                continue
            tn = t.get("thought_number")
            if not isinstance(tn, int):
                continue
            cur = best.get(tn)
            if cur is None:
                best[tn] = t
            else:
                a = _parse_dt(cur.get("updated_at")) or _parse_dt(cur.get("created_at"))
                b = _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at"))
                if b is not None and (a is None or b > a):
                    best[tn] = t
        rel_effective = list(best.values())
    else:
        rel_effective = rel

    components = sorted({t.get("game_component") for t in rel_effective if isinstance(t.get("game_component"), str) and t.get("game_component").strip()})
    libraries = sorted({t.get("library_used") for t in rel_effective if isinstance(t.get("library_used"), str) and t.get("library_used").strip()})

    counts = {"thoughts": len(rel_effective)}
    status_counts = {}
    for t in rel:
        st = t.get("status")
        status_counts[st] = status_counts.get(st, 0) + 1

    summary = {
        "session_id": sessionId,
        "branch_id": eff_branch,
        "distinct_game_components": components,
        "distinct_libraries_used": libraries,
        "counts": counts,
        "status_counts": status_counts,
        "latest_thought_updated_at": (latest_dt.isoformat() + "Z") if latest_dt is not None else None,
    }

    # Store cache on session
    sess["last_summary_cache"] = {"branch_id": eff_branch, "updated_at": now, "summary": summary}
    sess["updated_at"] = now
    _save("game_design_sessions.json", sessions)

    _log("ok")
    return {"summary": summary, "from_cache": False, "branch_id": eff_branch}

def listGameDesignSessions(status=None, gameTitleContains=None, updatedAfter=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0091000" if __import__("os").path.isdir("./environment_mix/0091000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Usage log (best-effort if file missing)
    def _log(endpoint, status_code, credential_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "id": "rl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "BAD"
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "BAD"
            return obj
        except Exception:
            return "BAD"

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate
    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "active", "archived"):
            _log("listGameDesignSessions", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'status' value.")
    if gameTitleContains is not None and not isinstance(gameTitleContains, str):
        _log("listGameDesignSessions", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'gameTitleContains' value; must be string.")
    if updatedAfter is not None:
        dt = _parse_dt(updatedAfter)
        if dt is None:
            _log("listGameDesignSessions", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'updatedAfter' date-time.")
    else:
        dt = None
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("listGameDesignSessions", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit'; must be integer in [1, 200].")
    else:
        limit = 50

    cur = _decode_cursor(cursor)
    if cur == "BAD":
        _log("listGameDesignSessions", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed 'cursor'.")
    # Cursor carries an offset into a deterministic ordering
    offset = 0
    if isinstance(cur, dict):
        if "offset" not in cur or not isinstance(cur["offset"], int) or cur["offset"] < 0:
            _log("listGameDesignSessions", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed 'cursor'.")
        offset = cur["offset"]

    sessions = _load("game_design_sessions.json")

    # Filter
    out = []
    needle = gameTitleContains.lower() if isinstance(gameTitleContains, str) else None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if needle is not None:
            title = s.get("game_title")
            if not isinstance(title, str) or needle not in title.lower():
                continue
        if dt is not None:
            s_up = s.get("updated_at")
            sdt = _parse_dt(s_up) if isinstance(s_up, str) else None
            if sdt is None or not (sdt > dt):
                continue
        out.append(s)

    # Sort updated_at desc (fallback created_at, id)
    def _sort_key(s):
        s_up = _parse_dt(s.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        s_cr = _parse_dt(s.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (s_up, s_cr, str(s.get("id", "")))

    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    page = out[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    resp = {
        "sessions": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor, "limit": limit}
    }
    _log("listGameDesignSessions", "OK")
    return resp

