    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rl_" + uuid.uuid4().hex,
            "endpoint": "updateGameDesignSession",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "session_id": sessionId,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(sessionId, str) or not sessionId:
        e = _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", field="sessionId")
        _log("error", e)
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "active", "archived"):
            e = _err("VALIDATION_ERROR", "status must be one of: draft, active, archived.", field="status")
            _log("error", e)
            return e

    # currentBranchId: allow None for main
    if currentBranchId is not None:
        if not isinstance(currentBranchId, str):
            e = _err("VALIDATION_ERROR", "currentBranchId must be a string or null.", field="currentBranchId")
            _log("error", e)
            return e
        if len(currentBranchId) > 128:
            e = _err("VALIDATION_ERROR", "currentBranchId length must be <= 128.", field="currentBranchId", max_length=128)
            _log("error", e)
            return e
        if currentBranchId == "":
            e = _err("VALIDATION_ERROR", "currentBranchId cannot be empty string; use null for main.", field="currentBranchId")
            _log("error", e)
            return e

    if totalThoughtsEstimate is not None:
        if not isinstance(totalThoughtsEstimate, int) or totalThoughtsEstimate < 1:
            e = _err("VALIDATION_ERROR", "totalThoughtsEstimate must be an integer >= 1.", field="totalThoughtsEstimate", minimum=1)
            _log("error", e)
            return e

    sessions = _load("game_design_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break
    if sess is None:
        e = _err("NOT_FOUND", "Session not found.", sessionId=sessionId)
        _log("error", e)
        return e

    # Enforce lifecycle transitions
    if status is not None and status != sess.get("status"):
        cur = sess.get("status")
        allowed = {"draft": ["active", "archived"], "active": ["archived"], "archived": []}
        if cur not in allowed or status not in allowed[cur]:
            e = _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)
            _log("error", e)
            return e
        sess["status"] = status

    if currentBranchId is not None:
        sess["current_branch_id"] = currentBranchId
    if totalThoughtsEstimate is not None:
        sess["total_thoughts_estimate"] = totalThoughtsEstimate

    sess["updated_at"] = now
    _save("game_design_sessions.json", sessions)

    _log("ok")
    return {"session": sess}

def listDesignThoughts(sessionId, branchId=None, status=None, fromThoughtNumber=None, toThoughtNumber=None, includeUiComponents=None, includeShaders=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0091000" if __import__("os").path.isdir("./environment_mix/0091000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rl_" + uuid.uuid4().hex,
            "endpoint": "listDesignThoughts",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "session_id": sessionId,
        }
        if branchId is not None:
            row["branch_id"] = branchId
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "BAD"
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "BAD"
            return obj
        except Exception:
            return "BAD"

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    if not isinstance(sessionId, str) or not sessionId:
        e = _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", field="sessionId")
        _log("error", e)
        return e
    if branchId is not None and not isinstance(branchId, str):
        e = _err("VALIDATION_ERROR", "branchId must be a string.", field="branchId")
        _log("error", e)
        return e
    if status is not None:
        if not isinstance(status, str) or status not in ("recorded", "superseded", "deleted"):
            e = _err("VALIDATION_ERROR", "status must be one of: recorded, superseded, deleted.", field="status")
            _log("error", e)
            return e
    if fromThoughtNumber is not None and (not isinstance(fromThoughtNumber, int) or fromThoughtNumber < 1):
        e = _err("VALIDATION_ERROR", "fromThoughtNumber must be an integer >= 1.", field="fromThoughtNumber", minimum=1)
        _log("error", e)
        return e
    if toThoughtNumber is not None and (not isinstance(toThoughtNumber, int) or toThoughtNumber < 1):
        e = _err("VALIDATION_ERROR", "toThoughtNumber must be an integer >= 1.", field="toThoughtNumber", minimum=1)
        _log("error", e)
        return e
    if includeUiComponents is not None and not isinstance(includeUiComponents, bool):
        e = _err("VALIDATION_ERROR", "includeUiComponents must be a boolean.", field="includeUiComponents")
        _log("error", e)
        return e
    if includeShaders is not None and not isinstance(includeShaders, bool):
        e = _err("VALIDATION_ERROR", "includeShaders must be a boolean.", field="includeShaders")
        _log("error", e)
        return e
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.", field="limit", minimum=1, maximum=500)
            _log("error", e)
            return e

    limit = limit if limit is not None else 100
    includeUiComponents = bool(includeUiComponents) if includeUiComponents is not None else False
    includeShaders = bool(includeShaders) if includeShaders is not None else False

    cur = _decode_cursor(cursor)
    if cur == "BAD":
        e = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        _log("error", e)
        return e

    sessions = _load("game_design_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break
    if sess is None:
        e = _err("NOT_FOUND", "Session not found.", sessionId=sessionId)
        _log("error", e)
        return e

    eff_branch = branchId if branchId is not None else None

    thoughts = _load("design_thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []

    filtered = []
    for t in thoughts:
        if not isinstance(t, dict):
            continue
        if t.get("session_id") != sessionId:
            continue
        if (t.get("branch_id") if t.get("branch_id") is not None else None) != eff_branch:
            continue
        if status is not None and t.get("status") != status:
            continue
        tn = t.get("thought_number")
        if isinstance(fromThoughtNumber, int) and isinstance(tn, int) and tn < fromThoughtNumber:
            continue
        if isinstance(toThoughtNumber, int) and isinstance(tn, int) and tn > toThoughtNumber:
            continue
        filtered.append(t)

    filtered.sort(key=lambda x: (x.get("thought_number") if isinstance(x.get("thought_number"), int) else 10**9, x.get("created_at") or ""))

    start = 0
    if isinstance(cur, dict):
        # cursor contains last seen (thought_number, created_at, id)
        last_tn = cur.get("tn")
        last_ca = cur.get("ca")
        last_id = cur.get("id")
        if isinstance(last_tn, int) and isinstance(last_ca, str) and isinstance(last_id, str):
            for i, t in enumerate(filtered):
                if t.get("thought_number") == last_tn and t.get("created_at") == last_ca and t.get("id") == last_id:
                    start = i + 1
                    break

    page = filtered[start:start + limit]
    has_more = start + limit < len(filtered)

    uics_by_thought = {}
    shds_by_thought = {}
    if includeUiComponents:
        uics = _load("ui_components.json")
        if not isinstance(uics, list):
            uics = []
        for u in uics:
            if not isinstance(u, dict):
                continue
            tid = u.get("thought_id")
            if isinstance(tid, str):
                uics_by_thought.setdefault(tid, []).append(u)
    if includeShaders:
        shds = _load("shader_effects.json")
        if not isinstance(shds, list):
            shds = []
        for s in shds:
            if not isinstance(s, dict):
                continue
            tid = s.get("thought_id")
            if isinstance(tid, str):
                shds_by_thought.setdefault(tid, []).append(s)

    out = []
    for t in page:
        row = dict(t)
        if includeUiComponents:
            row["ui_components"] = uics_by_thought.get(t.get("id"), [])
        if includeShaders:
            row["shader_effects"] = shds_by_thought.get(t.get("id"), [])
        out.append(row)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"tn": last.get("thought_number"), "ca": last.get("created_at"), "id": last.get("id")})

    _log("ok")
    return {
        "thoughts": out,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
